begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
select ok(not has_function_privilege('authenticated','internal.read_intelligence_run_status(integer,uuid,uuid)','EXECUTE'),'Browser role cannot read private run status');
select ok(not has_function_privilege('cuevo_worker','internal.read_intelligence_run_status(integer,uuid,uuid)','EXECUTE'),'Worker cannot impersonate a teacher status reader');
insert into app.intelligence_policies(school_id,version,fixture_enabled,approved_by)values('10000000-0000-4000-8000-000000000001',1,true,'20000000-0000-4000-8000-000000000001')on conflict(school_id)do update set fixture_enabled=true,version=1;
create temporary table status_source(result uuid,reservation jsonb);grant select,insert,update on status_source to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','9d100000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Reconcilable analysis','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id,policy_version)values('10000000-0000-4000-8000-000000000001','9d140000-0000-4000-8000-000000000001','9d100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Status source','School task',10,'61000000-0000-4000-8000-000000000001',2);
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','9d150000-0000-4000-8000-000000000001','9d140000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','Private source answer never returned in status');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
insert into status_source(result)values(internal.release_marking(internal.mark_submission('9d150000-0000-4000-8000-000000000001',3,'Teacher reviewed',2,0,true),1,false));
update status_source set reservation=internal.begin_teacher_insight_run('status-expiry',repeat('a',64),result,'{"mode":"FIXTURE","provider":"deterministic-fixture","model":"source-locked-v1","promptId":"next-learning-action","promptVersion":"2","promptDigest":"1f892110e486d0f8117e53ef9d9cf0a884b7c155821dd8eb1284cef22b9f0de4","policyVersion":1,"timeoutMs":30000,"maxTokens":1000,"maxCost":1,"costBasis":"DETERMINISTIC_FIXTURE"}','status-fixture');
select is((internal.read_intelligence_run_status(25,null,(select(reservation->>'runId')::uuid from status_source))->'items'->0->>'state'),'REASONING','Active source reservation is visible to its own current actor');
reset role;
update app.intelligence_runs set lease_until=clock_timestamp()-interval'1 second'where id=(select(reservation->>'runId')::uuid from status_source);
set local role cuevo_api;
select is((internal.read_intelligence_run_status(25,null,(select(reservation->>'runId')::uuid from status_source))->'items'->0->>'state'),'FAILED','Expired status read closes a durable timeout without a model call');
select ok(not(internal.read_intelligence_run_status(25,null,(select(reservation->>'runId')::uuid from status_source))->'items'->0?'contextReferences'),'Status returns no raw context');
select ok(not(internal.read_intelligence_run_status(25,null,(select(reservation->>'runId')::uuid from status_source))->'items'->0?'leaseToken'),'Status returns no lease capability');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok($$select internal.read_intelligence_run_status(25,null,(select(reservation->>'runId')::uuid from status_source))$$,'42501',null,'Parent cannot read staff analysis status');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000005',true);
select throws_ok($$select internal.read_intelligence_run_status(25,null,(select(reservation->>'runId')::uuid from status_source))$$,'42501',null,'Another teacher cannot read this actor run');
reset role;
select is((select count(*)from app.recommendations where intelligence_run_id=(select(reservation->>'runId')::uuid from status_source)),0::bigint,'Timeout status never creates a proposal or automatic practice');
select is((select count(*)from internal.audit_events where entity_id=(select(reservation->>'runId')::uuid from status_source)and action='intelligence.failed'),1::bigint,'Repeated status reconciliation writes one failure audit');
select*from finish();rollback;
